"""Event ordering."""


def order_events(events):
    """Return events ordered by priority then timestamp."""
    return sorted(events, key=lambda e: (e["priority"], e["timestamp"], e["name"]))

verification_tests:
from target import order_events


def test_priority_is_respected():
    events = [
        {"name": "b", "priority": 2, "timestamp": "2024-01-01"},
        {"name": "a", "priority": 1, "timestamp": "2024-01-01"},
    ]
    assert [e["name"] for e in order_events(events)] == ["a", "b"]


def test_ties_keep_input_order():
    events = [
        {"name": "z", "priority": 1, "timestamp": "2024-01-01"},
        {"name": "a", "priority": 1, "timestamp": "2024-01-01"},
    ]
    assert [e["name"] for e in order_events(events)] == ["z", "a"]


def test_timestamp_orders_same_priority_events():
    events = [
        {"name": "second", "priority": 1, "timestamp": "2024-02-01"},
        {"name": "first", "priority": 1, "timestamp": "2024-01-01"},
    ]
    assert [e["name"] for e in order_events(events)] == ["first", "second"]
